/** TypeScript versions of the API's product types. */

/** Stock indicator calculated by the API. */
export type StockStatus = 'OutOfStock' | 'LowStock' | 'InStock';

/** Why a product's stock changed. */
export type StockMovementType = 'InitialStock' | 'Increment' | 'Decrement' | 'Adjustment';

/** A product as returned by the list endpoints. */
export interface Product {
  /** Unique 6-digit id, generated by the database. */
  readonly id: number;
  readonly name: string;
  readonly description?: string;
  readonly price: number;
  readonly stockQuantity: number;
  readonly lowStockThreshold: number;
  readonly stockStatus: StockStatus;
  readonly categoryId: number;
  readonly categoryName?: string;
  readonly createdAt: string;
  readonly updatedAt: string;
}

/** One entry in a product's stock history. */
export interface StockMovement {
  readonly id: number;
  readonly type: StockMovementType;
  /** Positive when stock was added, negative when removed. */
  readonly quantityChange: number;
  readonly resultingStock: number;
  readonly reason?: string;
  readonly occurredAt: string;
}

/** A single product, including its stock history. */
export interface ProductDetail extends Product {
  readonly stockMovements: readonly StockMovement[];
}

/** Body sent when creating a product. */
export interface CreateProductRequest {
  readonly name: string;
  readonly description?: string;
  readonly price: number;
  readonly initialStock: number;
  readonly lowStockThreshold: number;
  readonly categoryId: number;
}

/** Body sent when updating a product. */
export interface UpdateProductRequest {
  readonly name: string;
  readonly description?: string;
  readonly price: number;
  readonly lowStockThreshold: number;
  readonly categoryId: number;
  /** Optional. Set it to overwrite the stock level. */
  readonly stockQuantity?: number;
}

/** Response from the add-to-stock and decrement-stock endpoints. */
export interface StockOperationResult {
  readonly productId: number;
  readonly name: string;
  readonly previousStock: number;
  readonly newStock: number;
  readonly stockStatus: StockStatus;
}

/** A product category. */
export interface Category {
  readonly id: number;
  readonly name: string;
  readonly description?: string;
  readonly productCount: number;
}
